// [vite-esm] imports auto-generated by the 2026-07 Vite migration.
import "../state.js";

/**
 * Substitution planning engine — policy, ranking, and whole-day auto-fill.
 *
 * Ported from the school's standalone GDGPSD Substitution Planner (v3.16,
 * Apps Script). That planner's ranking was materially better than Chronexa's
 * first cut: it scored against a policy table instead of four hard-coded
 * bonuses, reserved early-years class teachers, respected a per-day ceiling and
 * a rolling 7-day load, avoided long consecutive runs, assigned a period's
 * slots as ONE optimisation (so two vacancies never fight over the same free
 * teacher), and knew about duty pools, co-teachers and merged classes.
 *
 * Nothing here touches the DOM or APP.school: it takes a plain `plan` and a
 * `school` and returns numbers. `main.js` owns building/persisting the plan,
 * `classwise_output.js` owns the UI. Keeping the policy pure is deliberate —
 * the scoring is the part that has to be provable, and it is unit-tested.
 *
 * Plan shape (see main.js buildPlan):
 *   { date, day, absent:[{teacherId, type}], dutyPool:[teacherId],
 *     slots:[slot], actingCT:{classId: teacherId} }
 *   slot = { slotKey, period, classId, classSection, subjectId, subject,
 *            absentTeacherId, absentTeacher, cardId, classroomId,
 *            status: "PENDING"|"FILLED"|"SUPERVISED"|"CANCELLED"|"RESCHEDULE",
 *            type: "SUB"|"SUPERVISION"|"CANCEL",
 *            substituteTeacherId, mergedWithKey, movedFrom, note }
 */

/** The school's own weights. Kept as one table so the reason string the user
 *  sees is always the number the sort used. */
export const POLICY = Object.freeze({
  minimumScore: 30,             // below this, leave it for a human
  dutyPoolBonus: 200,           // already on duty that day — pays for itself
  coTeacherBonus: 120,          // co-teaches this class in this period
  sameSubjectBonus: 100,
  sameClassBonus: 30,
  classTeacherBonus: 25,
  continuityBonus: 20,          // covered this class the period before
  adjacentLessonBonus: 15,      // free on one side of the period, teaching the other
  todayAssignmentPenalty: 5,    // per substitution already taken today
  recentAssignmentPenalty: 2,   // per substitution in the last 7 days
  preferredDailyMaximum: 2,     // beyond this the penalty escalates
  overDailyMaximumPenalty: 40,
  preferredConsecutiveMaximum: 3,
  overConsecutivePenalty: 25,
  mergedClassBonus: 30,
  motherTeacherPenalty: 100,    // early-years class teacher protection
  swapRequiredPenalty: 3,
  coverageBonus: 100000,        // covering one more slot beats any score
});

export const STATUS = Object.freeze({
  PENDING: "PENDING",
  FILLED: "FILLED",
  SUPERVISED: "SUPERVISED",
  CANCELLED: "CANCELLED",
  RESCHEDULE: "RESCHEDULE",
});

/**
 * Absent teachers as ids. `plan.absent` is an array of IDS — that is what the
 * chips, the tabs and the tests read — while older code passed objects
 * ({teacherId, type}). Accept both, always, so neither shape crashes the other.
 */
export const absentIdsOf = (plan) =>
  ((plan && plan.absent) || [])
    .map((a) => (typeof a === "string" ? a : a && a.teacherId))
    .filter(Boolean);

export const isFilled = (slot) =>
  !!slot && (slot.status === STATUS.FILLED || slot.status === STATUS.SUPERVISED) && !!slot.substituteTeacherId;

export const slotKey = (slot) =>
  slot && slot.slotKey
    ? slot.slotKey
    : `${slot.period}::${slot.classId}::${slot.absentTeacherId}`;

// ── school lookups ──────────────────────────────────────────────────────────

/**
 * The timetable as rows of { card, lesson, classIds, subjectId }.
 *
 * Deliberately reads school.cards + school.lessons rather than the `_idx` index.
 * `_idx` comes in two shapes: the importer enriches each indexed card with its
 * lesson's classes and subject, while the undo layer's buildIndex() pushes the
 * RAW card. Any mutation (recording an absence is one) swaps in the second
 * shape, and code that trusted the enrichment then sees no subjects and no
 * classes — which silently ranked every teacher at 0 and filled nothing.
 */
export function timetableRows(school) {
  const lessonById = (school._idx && school._idx.lessonById) ||
    Object.fromEntries((school.lessons || []).map((l) => [l.id, l]));
  const rows = [];
  for (const card of school.cards || []) {
    const base = String(card.lessonId || "").replace(/#\d+$/, "");
    const lesson = lessonById[base] || lessonById[card.lessonId];
    if (!lesson) continue;
    rows.push({
      card,
      lesson,
      classIds: lesson.classIds || [],
      subjectId: lesson.subjectId || "",
      teacherIds: lesson.teacherIds || [],
    });
  }
  return rows;
}

/** Teachers per (day|period) → Set of teacher ids with a lesson then. */
function busySets(school, day, rows) {
  const out = new Map();
  for (const t of school.teachers || []) out.set(t.id, new Set());
  for (const row of rows || timetableRows(school)) {
    if (row.card.day !== day) continue;
    for (const tid of row.teacherIds) {
      if (!out.has(tid)) out.set(tid, new Set());
      out.get(tid).add(row.card.period);
    }
  }
  return out;
}

/** classId → teacherId, when the class has a homeroom/class teacher. */
export function classTeacherMap(school) {
  const out = Object.create(null);
  for (const c of school.classes || []) {
    const tid = c.classTeacherId || c._teacherId || c.classTeacher || null;
    if (tid) out[c.id] = tid;
  }
  return out;
}

/**
 * Early-years protection. The standalone planner reserves the class teacher of
 * the youngest children (they do not leave a nursery class with a stranger),
 * and never auto-assigns them. Configurable; defaults to the classes whose name
 * starts with Nursery/LKG/UKG or a single-letter "I/A" style first class.
 */
export function motherTeacherMap(school) {
  const out = Object.create(null);
  const ct = classTeacherMap(school);
  const protect = school.substitution?.protectClassTeachers;
  const names = protect === true ? null : (Array.isArray(protect) ? protect : null);
  for (const c of school.classes || []) {
    const tid = ct[c.id];
    if (!tid) continue;
    const label = String(c.name || c.short || "");
    const early = names
      ? names.some((n) => label.trim().toLowerCase().startsWith(String(n).toLowerCase()))
      : /^(nursery|nur|kg|lkg|ukg|prep)/i.test(label);
    if (early) out[tid] = c.name || c.id;
  }
  return out;
}

/**
 * What each teacher actually teaches, derived from the timetable.
 *
 * The standalone planner had these as data tables (teacherSubjects /
 * teacherClasses). Chronexa's teacher records carry no subject or class lists —
 * the timetable is the truth — so derive them from the cards, and honour an
 * explicit list when a school does provide one.
 */
export function teacherSubjectClassSets(school, rows) {
  const subjects = Object.create(null);
  const classes = Object.create(null);
  for (const t of school.teachers || []) {
    subjects[t.id] = new Set(t.subjectIds || t.subjects || []);
    classes[t.id] = new Set(t.classIds || []);
  }
  for (const row of rows || timetableRows(school)) {
    for (const tid of row.teacherIds) {
      if (!subjects[tid]) { subjects[tid] = new Set(); classes[tid] = new Set(); }
      if (row.subjectId) subjects[tid].add(row.subjectId);
      for (const cid of row.classIds) classes[tid].add(cid);
    }
  }
  return { subjects, classes };
}

/** Rolling 7-day substitution load per teacher, from saved history. */
export function recentLoad(school, date, days = 7) {
  const out = Object.create(null);
  const end = Date.parse(date);
  if (!Number.isFinite(end)) return out;
  const start = end - days * 86400000;
  for (const sub of school.substitutions || []) {
    if (!sub || !sub.substituteTeacherId) continue;
    if (!(sub.status === undefined || sub.status === STATUS.FILLED || sub.status === STATUS.SUPERVISED)) continue;
    const t = Date.parse(sub.date);
    if (!(t >= start && t < end)) continue;
    out[sub.substituteTeacherId] = (out[sub.substituteTeacherId] || 0) + 1;
  }
  return out;
}

/** Last date each teacher substituted — the fairness tie-break. */
export function lastAssigned(school) {
  const out = Object.create(null);
  for (const sub of school.substitutions || []) {
    if (!sub || !sub.substituteTeacherId) continue;
    const prev = out[sub.substituteTeacherId];
    if (!prev || String(sub.date) > String(prev)) out[sub.substituteTeacherId] = sub.date;
  }
  return out;
}

// ── context for one slot ────────────────────────────────────────────────────

/**
 * Everything a candidate's score depends on, computed once per slot.
 * `plan` may be a hypothetical copy (that is how the auto-fill previews).
 */
export function buildSlotContext(school, plan, slot, rows) {
  const day = plan.day;
  const period = slot.period;
  const timetable = rows || timetableRows(school);
  const busy = busySets(school, day, timetable);
  const absent = new Set(absentIdsOf(plan));
  const ctMap = classTeacherMap(school);
  const mother = motherTeacherMap(school);

  // Substitutions already made today (outside this slot), counted per period so
  // two slots of the same period cannot quietly double-book one teacher.
  const allocated = Object.create(null);
  const todayExtras = Object.create(null);
  const counted = new Set();
  for (const s of plan.slots || []) {
    if (s === slot || !isFilled(s)) continue;
    const key = `${s.substituteTeacherId}|${s.period}`;
    if (!counted.has(key)) {
      counted.add(key);
      todayExtras[s.substituteTeacherId] = (todayExtras[s.substituteTeacherId] || 0) + 1;
    }
    if (s.period === period) allocated[s.substituteTeacherId] = s;
  }

  // Whoever covered this class in the previous period.
  let continuity = null;
  for (const s of plan.slots || []) {
    if (s === slot) continue;
    if (s.classId === slot.classId && +s.period === +period - 1 && isFilled(s)) {
      continuity = s.substituteTeacherId;
      break;
    }
  }

  // The class's class teacher (explicit, else the teacher who teaches it most
  // that day — the standalone planner's fallback).
  let ctTeacher = ctMap[slot.classId] || null;
  let ctLoad = ctTeacher ? 4 : 0;
  if (!ctTeacher) {
    const load = Object.create(null);
    for (const row of timetable) {
      if (row.card.day !== day) continue;
      if (!row.classIds.includes(slot.classId)) continue;
      for (const tid of row.teacherIds) load[tid] = (load[tid] || 0) + 1;
    }
    for (const tid of Object.keys(load)) {
      if (load[tid] > ctLoad) { ctLoad = load[tid]; ctTeacher = tid; }
    }
  }

  // Co-teachers already in this room this period (a co-taught class can absorb
  // an absence without a substitute at all).
  const coTeachers = Object.create(null);
  for (const row of timetable) {
    if (row.card.day !== day || row.card.period !== period) continue;
    if (!row.classIds.includes(slot.classId)) continue;
    const subject = (school._idx?.subjectById?.[row.subjectId])?.name || "";
    for (const tid of row.teacherIds) {
      if (absent.has(tid) || tid === slot.absentTeacherId) continue;
      coTeachers[tid] = subject;
    }
  }

  return {
    day, period, busy, absent, ctMap, mother, allocated, todayExtras,
    continuity, ctTeacher, ctLoad, coTeachers,
    dutyPool: new Set(plan.dutyPool || []),
  };
}

/** Teaching streak a candidate would have if given this slot (regular lessons
 *  plus this day's substitutions). Used to avoid burning a teacher out. */
export function prospectiveStreak(school, plan, slot, teacherId, rows) {
  const occupied = new Set();
  for (const row of rows || timetableRows(school)) {
    if (row.card.day !== plan.day) continue;
    if (!row.teacherIds.includes(teacherId)) continue;
    occupied.add(+row.card.period);
  }
  for (const s of plan.slots || []) {
    if (s === slot) continue;
    if (s.substituteTeacherId === teacherId && isFilled(s)) occupied.add(+s.period);
  }
  const target = +slot.period;
  occupied.add(target);
  let start = target, end = target;
  while (occupied.has(start - 1)) start--;
  while (occupied.has(end + 1)) end++;
  return end - start + 1;
}

// ── ranking ─────────────────────────────────────────────────────────────────

function fairCompare(a, b, lastBy) {
  if (b.score !== a.score) return b.score - a.score;
  const ad = lastBy[a.teacherId] || "";
  const bd = lastBy[b.teacherId] || "";
  if (ad !== bd) {
    if (!ad) return -1;
    if (!bd) return 1;
    return ad.localeCompare(bd);
  }
  return String(a.teacher || "").localeCompare(String(b.teacher || ""));
}

/**
 * Candidates for one slot, best first, each with the arithmetic that produced
 * its score. `opts.forAuto` skips early-years class teachers (they are never
 * chosen automatically — a human may still pick them).
 */
export function rankCandidates(school, plan, slot, opts = {}) {
  const rows = opts.rows || timetableRows(school);
  const ctx = opts.ctx || buildSlotContext(school, plan, slot, rows);
  const recent = opts.recent || recentLoad(school, plan.date);
  const lastBy = opts.lastBy || lastAssigned(school);
  const taught = opts.taught || teacherSubjectClassSets(school, rows);
  const out = [];

  for (const t of school.teachers || []) {
    const tid = t.id;
    const isCo = !!ctx.coTeachers[tid];
    const isMother = !!ctx.mother[tid];
    const already = ctx.allocated[tid] || null;
    // `busy` is a MAP of teacher → set of periods. Testing the map would exclude
    // anyone teaching at all that day, which silently hid most of the staff.
    const busySet = ctx.busy.get(tid) || new Set();
    if (ctx.absent.has(tid)) continue;
    if (busySet.has(+slot.period) && !isCo) continue;     // teaching this period
    if (already && !opts.allowSwap) continue;             // already covering this period
    if (opts.forAuto && isMother) continue;

    let score = 0;
    const why = [];
    const warnings = [];
    const breakdown = [];
    const add = (points, label) => {
      score += points;
      breakdown.push({ points, label });
      if (points > 0) why.push(label);
      else if (points < 0) warnings.push(`${label} (${points})`);
    };

    if (ctx.dutyPool.has(tid)) add(POLICY.dutyPoolBonus, "on duty");
    if (isCo) add(POLICY.coTeacherBonus, "co-teaches this class");
    if (slot.subjectId && taught.subjects[tid] && taught.subjects[tid].has(slot.subjectId)) {
      add(POLICY.sameSubjectBonus, `teaches ${slot.subject || "this subject"}`);
    }
    if (slot.classId && taught.classes[tid] && taught.classes[tid].has(slot.classId)) {
      add(POLICY.sameClassBonus, `teaches ${slot.classSection || "this class"}`);
    }
    if (tid === ctx.ctTeacher && ctx.ctLoad >= 4) add(POLICY.classTeacherBonus, "class teacher");
    if (ctx.continuity === tid) add(POLICY.continuityBonus, "covered previous period");

    // Teaching on exactly one side of this period — a free middle reads better
    // than a gap in the middle of a busy day.
    const adjacent = busySet.has(+slot.period - 1) !== busySet.has(+slot.period + 1);
    if (adjacent) add(POLICY.adjacentLessonBonus, "adjacent lesson");

    const todayN = ctx.todayExtras[tid] || 0;
    const weekN = recent[tid] || 0;
    if (todayN) add(-todayN * POLICY.todayAssignmentPenalty, `${todayN} already today`);
    if (weekN) add(-weekN * POLICY.recentAssignmentPenalty, `${weekN} in the last 7 days`);
    if (todayN >= POLICY.preferredDailyMaximum) {
      add(-(todayN - POLICY.preferredDailyMaximum + 1) * POLICY.overDailyMaximumPenalty, "above preferred daily load");
    }
    const streak = prospectiveStreak(school, plan, slot, tid, rows);
    if (streak > POLICY.preferredConsecutiveMaximum) {
      add(-(streak - POLICY.preferredConsecutiveMaximum) * POLICY.overConsecutivePenalty, `${streak} consecutive periods`);
    }
    if (isMother) add(-POLICY.motherTeacherPenalty, "early-years class teacher protected");
    if (already) add(-POLICY.swapRequiredPenalty, "swap required");

    const teacher = t;
    out.push({
      teacherId: tid,
      teacher: teacher.name || teacher.abbr || tid,
      abbr: teacher.abbr || "",
      score,
      why,
      warnings,
      reasons: why,                     // legacy name used by the old UI
      breakdown,
      today: todayN,
      week: weekN,
      isCT: tid === ctx.ctTeacher && ctx.ctLoad >= 4,
      isCoTeacher: isCo,
      coSubject: ctx.coTeachers[tid] || "",
      isMother,
      motherClass: ctx.mother[tid] || "",
      alreadyInSlot: already,
      isOnDuty: ctx.dutyPool.has(tid),
      prospectiveStreak: streak,
    });
  }
  return out.sort((a, b) => fairCompare(a, b, lastBy));
}

/** Rank candidates for a group of slots that must share ONE substitute (merged
 *  classes). A candidate must be eligible for every slot in the group. */
export function rankCandidatesForGroup(school, plan, members, opts = {}) {
  const lists = members.map((slot) => {
    const byId = Object.create(null);
    for (const c of rankCandidates(school, plan, slot, { ...opts, allowSwap: false, forAuto: true })) {
      byId[c.teacherId] = c;
    }
    return byId;
  });
  const lastBy = opts.lastBy || lastAssigned(school);
  const out = [];
  for (const t of school.teachers || []) {
    const matches = lists.map((m) => m[t.id]);
    if (matches.some((x) => !x)) continue;
    let score = Math.round(matches.reduce((sum, c) => sum + c.score, 0) / matches.length);
    if (members.length > 1) score += POLICY.mergedClassBonus;
    if (score < POLICY.minimumScore) continue;
    const why = [];
    const warnings = [];
    for (const c of matches) {
      for (const r of c.why) if (!why.includes(r)) why.push(r);
      for (const b of c.breakdown) {
        if (b.points < 0) {
          const w = `${b.label} (${b.points})`;
          if (!warnings.includes(w)) warnings.push(w);
        }
      }
    }
    if (members.length > 1) why.unshift("keeps merged classes together");
    out.push({
      teacherId: t.id,
      teacher: t.name || t.abbr || t.id,
      score, why, reasons: why, warnings,
      today: Math.max(...matches.map((c) => c.today)),
      week: Math.max(...matches.map((c) => c.week)),
    });
  }
  return out.sort((a, b) => fairCompare(a, b, lastBy));
}

// ── Hungarian assignment (max weight, rectangular) ──────────────────────────

export function hungarianMax(weights) {
  const n = weights.length;
  if (!n) return [];
  const m = weights[0].length;
  const u = new Array(n + 1).fill(0);
  const v = new Array(m + 1).fill(0);
  const p = new Array(m + 1).fill(0);
  const way = new Array(m + 1).fill(0);
  for (let i = 1; i <= n; i++) {
    p[0] = i;
    let j0 = 0;
    const minv = new Array(m + 1).fill(Infinity);
    const used = new Array(m + 1).fill(false);
    do {
      used[j0] = true;
      const i0 = p[j0];
      let delta = Infinity, j1 = 0;
      for (let j = 1; j <= m; j++) {
        if (used[j]) continue;
        const cur = -weights[i0 - 1][j - 1] - u[i0] - v[j];
        if (cur < minv[j]) { minv[j] = cur; way[j] = j0; }
        if (minv[j] < delta) { delta = minv[j]; j1 = j; }
      }
      for (let j = 0; j <= m; j++) {
        if (used[j]) { u[p[j]] += delta; v[j] -= delta; }
        else minv[j] -= delta;
      }
      j0 = j1;
    } while (p[j0] !== 0);
    do {
      const j1 = way[j0];
      p[j0] = p[j1];
      j0 = j1;
    } while (j0 !== 0);
  }
  const assignment = new Array(n).fill(-1);
  for (let j = 1; j <= m; j++) if (p[j]) assignment[p[j] - 1] = j - 1;
  return assignment;
}

/** Groups of pending slots for one period: each merged pair travels together,
 *  everything else is its own group. */
export function pendingGroups(plan, period) {
  const groups = [];
  const seen = new Set();
  for (const slot of plan.slots || []) {
    if (seen.has(slot) || +slot.period !== +period || slot.status !== STATUS.PENDING) continue;
    const members = [slot];
    seen.add(slot);
    if (slot.mergedWithKey) {
      const partner = (plan.slots || []).find((s) => slotKey(s) === slot.mergedWithKey);
      if (partner && partner !== slot && +partner.period === +period && partner.status === STATUS.PENDING) {
        members.push(partner);
        seen.add(partner);
      }
    }
    groups.push(members);
  }
  return groups;
}

/**
 * Assign one period's groups in a single optimisation. Covering one more slot
 * is worth more than any amount of candidate quality (coverageBonus), and slots
 * left over get a null candidate so the UI can name them as gaps.
 */
export function optimisePeriod(school, plan, period, opts = {}) {
  const groups = pendingGroups(plan, period);
  if (!groups.length) return [];
  const rankings = groups.map((members) =>
    rankCandidatesForGroup(school, plan, members, opts)
  );
  const names = [...new Set(rankings.flat().map((c) => c.teacherId))];
  if (!names.length) return groups.map((members) => ({ members, candidate: null }));

  const IMPOSSIBLE = -1e8;
  const matrix = rankings.map((list) => {
    const byId = Object.create(null);
    for (const c of list) byId[c.teacherId] = c;
    return names
      .map((id) => (byId[id] ? POLICY.coverageBonus * 1 + byId[id].score : IMPOSSIBLE))
      .concat(new Array(groups.length).fill(0));   // dummy columns: leave empty
  });
  const picked = hungarianMax(matrix);
  return groups.map((members, i) => {
    const col = picked[i];
    if (col < 0 || col >= names.length) return { members, candidate: null };
    return { members, candidate: rankings[i].find((c) => c.teacherId === names[col]) || null };
  });
}

// ── acting class teacher ────────────────────────────────────────────────────

/**
 * When a class's own class teacher is absent, someone covers the ROLE
 * (attendance, line-up, dispersal) — not the period. Prefers a teacher already
 * taking that class today; workload is the tie-break.
 */
export function eligibleActingCTs(school, plan, classId) {
  const ctMap = classTeacherMap(school);
  const takenBy = new Set(
    Object.entries(plan.actingCT || {})
      .filter(([cls]) => cls !== classId)
      .map(([, tid]) => tid)
      .filter(Boolean)
  );
  const absent = new Set(absentIdsOf(plan));
  const recent = recentLoad(school, plan.date);
  const teachesToday = new Set();
  for (const row of timetableRows(school)) {
    if (row.card.day !== plan.day) continue;
    if (!row.classIds.includes(classId)) continue;
    for (const tid of row.teacherIds) if (!absent.has(tid)) teachesToday.add(tid);
  }
  const todayCount = Object.create(null);
  const counted = new Set();
  for (const s of plan.slots || []) {
    if (!isFilled(s)) continue;
    const key = `${s.substituteTeacherId}|${s.period}`;
    if (counted.has(key)) continue;
    counted.add(key);
    todayCount[s.substituteTeacherId] = (todayCount[s.substituteTeacherId] || 0) + 1;
  }

  const out = [];
  const holdsClass = new Set(Object.values(ctMap));
  for (const t of school.teachers || []) {
    // Someone else's class teacher already has a class to run that day.
    if (holdsClass.has(t.id)) continue;
    if (absent.has(t.id) || takenBy.has(t.id)) continue;
    const teachesClass = teachesToday.has(t.id);
    const today = todayCount[t.id] || 0;
    const week = recent[t.id] || 0;
    out.push({
      teacherId: t.id,
      teacher: t.name || t.abbr || t.id,
      stars: teachesClass ? 3 : 1,
      score: (teachesClass ? 100 : 0) - today * 10 - week * 2,
      why: teachesClass ? ["teaches this class today"] : ["available for administrator review"],
      today, week,
    });
  }
  return out.sort((a, b) => b.stars - a.stars || b.score - a.score);
}

// ── whole-day plan ──────────────────────────────────────────────────────────

/**
 * Fill every PENDING slot that the policy is willing to fill.
 * Returns a NEW plan plus the reasoning, so the UI can preview it before it is
 * applied and the caller can undo by keeping the old plan object.
 */
export function buildSmartPlan(school, plan) {
  const next = structuredClonePlan(plan);
  const recent = recentLoad(school, next.date);
  const lastBy = lastAssigned(school);
  const opts = { recent, lastBy };
  const assignments = [];
  const gaps = [];

  // 1. Keep merged partners together when one half is already decided.
  for (const slot of next.slots) {
    if (slot.status !== STATUS.PENDING || !slot.mergedWithKey) continue;
    const partner = next.slots.find((s) => slotKey(s) === slot.mergedWithKey);
    if (!partner || !isFilled(partner)) continue;
    slot.substituteTeacherId = partner.substituteTeacherId;
    slot.status = partner.status;
    slot.type = partner.type;
    slot.smartScore = partner.smartScore;
    slot.smartReason = "kept merged classes together";
    assignments.push({
      members: [slot],
      candidate: { teacherId: partner.substituteTeacherId, teacher: partner.substituteTeacher || "", score: partner.smartScore ?? "", why: ["kept merged classes together"], warnings: [] },
      repaired: true,
    });
  }

  // 2. One optimisation per period, so two vacancies never pick the same teacher.
  const periods = [...new Set(next.slots.filter((s) => s.status === STATUS.PENDING).map((s) => +s.period))].sort((a, b) => a - b);
  for (const period of periods) {
    const groups = pendingGroups(next, period);
    const solvable = [];
    for (const members of groups) {
      if (members.some((s) => s.status === STATUS.RESCHEDULE || s.mustReschedule)) {
        gaps.push({ members, reason: "reschedule rule — do not substitute" });
      } else {
        solvable.push(members);
      }
    }
    if (!solvable.length) continue;
    // optimisePeriod re-reads the plan's pending groups, so hand it a view in
    // which the reschedule-rule slots are no longer PENDING — otherwise they
    // compete for teachers and can steal one from a group that could be filled.
    const solvableSet = new Set(solvable.flat());
    const view = {
      ...next,
      slots: next.slots.map((s) =>
        +s.period === +period && s.status === STATUS.PENDING && !solvableSet.has(s)
          ? { ...s, status: STATUS.RESCHEDULE }
          : s
      ),
    };
    const results = optimisePeriod(school, view, period, opts);
    for (const r of results) {
      if (!r.candidate) {
        gaps.push({ members: r.members, reason: `no safe match reached score ${POLICY.minimumScore}` });
        continue;
      }
      const reason = r.candidate.why.slice(0, 3).join(" · ") || "best eligible workload balance";
      for (const slot of r.members) {
        slot.substituteTeacherId = r.candidate.teacherId;
        slot.substituteTeacher = r.candidate.teacher;
        slot.status = STATUS.FILLED;
        slot.type = slot.type === "SUPERVISION" ? "SUPERVISION" : "SUB";
        slot.smartScore = r.candidate.score;
        slot.smartReason = reason;
      }
      assignments.push(r);
    }
  }

  // 3. Acting class teacher for any absent homeroom teacher (3★ only).
  const actingAssignments = [];
  next.actingCT = next.actingCT || {};
  const ctMap = classTeacherMap(school);
  const ctReverse = Object.create(null);
  for (const classId of Object.keys(ctMap)) ctReverse[ctMap[classId]] = classId;
  for (const teacherId of absentIdsOf(next)) {
    const classId = ctReverse[teacherId];
    if (!classId || next.actingCT[classId]) continue;
    const cands = eligibleActingCTs(school, next, classId);
    if (cands.length && cands[0].stars >= 3) {
      next.actingCT[classId] = cands[0].teacherId;
      actingAssignments.push({ classId, absentTeacherId: teacherId, candidate: cands[0] });
    }
  }

  return { plan: next, assignments, gaps, actingAssignments };
}

function structuredClonePlan(plan) {
  const clone = (o) => (typeof structuredClone === "function" ? structuredClone(o) : JSON.parse(JSON.stringify(o)));
  return clone(plan);
}

// ── derived numbers for the UI ──────────────────────────────────────────────

export function planCounts(plan) {
  const slots = plan.slots || [];
  const filled = slots.filter((s) => isFilled(s)).length;
  const supervised = slots.filter((s) => s.status === STATUS.SUPERVISED).length;
  const cancelled = slots.filter((s) => s.status === STATUS.CANCELLED).length;
  const reschedule = slots.filter((s) => s.status === STATUS.RESCHEDULE).length;
  const pending = slots.filter((s) => s.status === STATUS.PENDING).length;
  return { total: slots.length, filled, supervised, cancelled, reschedule, pending, open: pending + reschedule };
}

/** Per-teacher load for the day + rolling week, for the workload strip. */
export function teacherLoad(school, plan) {
  const recent = recentLoad(school, plan.date);
  const rows = [];
  const todayPeriods = Object.create(null);
  for (const s of plan.slots || []) {
    if (!isFilled(s)) continue;
    const key = s.substituteTeacherId;
    (todayPeriods[key] = todayPeriods[key] || new Set()).add(s.period);
  }
  for (const t of school.teachers || []) {
    const today = todayPeriods[t.id] ? todayPeriods[t.id].size : 0;
    const week = recent[t.id] || 0;
    if (!today && !week) continue;
    rows.push({ teacherId: t.id, teacher: t.name || t.abbr || t.id, today, week, load: today + week });
  }
  return rows.sort((a, b) => b.today - a.today || b.week - a.week || String(a.teacher).localeCompare(String(b.teacher)));
}

/** Exposed for the unit tests only. */
export const __testHooks = { prospectiveStreak };

export const SmartPlanner = {
  POLICY, STATUS, isFilled, slotKey,
  timetableRows, teacherSubjectClassSets,
  absentIdsOf, classTeacherMap, motherTeacherMap, recentLoad, lastAssigned,
  buildSlotContext, prospectiveStreak, rankCandidates, rankCandidatesForGroup,
  hungarianMax, pendingGroups, optimisePeriod, eligibleActingCTs,
  buildSmartPlan, planCounts, teacherLoad,
};

if (typeof window !== "undefined") window.SmartPlanner = SmartPlanner;
